package com.novalearn.infrastructure.security;
import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List; import java.util.UUID;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtTokenService tokens; public JwtAuthenticationFilter(JwtTokenService tokens){this.tokens=tokens;}
 protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException { String header=request.getHeader(HttpHeaders.AUTHORIZATION); if(header!=null&&header.startsWith("Bearer ")){try{var claims=tokens.parse(header.substring(7)).getPayload();var auth=new UsernamePasswordAuthenticationToken(UUID.fromString(claims.getSubject()),null,List.of(new SimpleGrantedAuthority("ROLE_"+claims.get("role",String.class))));SecurityContextHolder.getContext().setAuthentication(auth);}catch(JwtException|IllegalArgumentException ignored){SecurityContextHolder.clearContext();}} chain.doFilter(request,response); }
}
